import type {AffairsAccount} from './affairsWorkspace.js';
export type DtmGradeCells={score:number|null;maximum:number|null;gradeText:string|null;rangeText:string|null;percentageText:string|null;weightText:string|null;weightNote:string|null;rankText:string|null;feedbackText:string|null;contributionText:string|null};
export type DtmGradeReportItem=DtmGradeCells&{id:string;label:string;activityKind:'assignment'|null};
export type DtmGradeReportContent={items:DtmGradeReportItem[];total:DtmGradeCells|null};
export type DtmGradeReportRecord=DtmGradeReportContent&{id:string;userId:string;courseId:string;sourceMode:'local_demo';version:number;createdAt:string;updatedAt:string};
export type DtmGradeReportData={report:DtmGradeReportRecord|null};
export type DtmGradeReportCourse={id:string;userId:string;title:string;code:string;term:string};
export type DtmGradeReportCoursesData={courses:DtmGradeReportCourse[];limit:100;nextCursor:string|null};
export type DtmGradeReportOverviewData={courses:(DtmGradeReportCourse&{gradeText:string|null})[];limit:100;nextCursor:string|null};
export type DtmGradeReportKind='save_dtm_grade_report'|'delete_dtm_grade_report';
export type DtmGradeReportTarget={id:string;user_id:string;course_id:string;request_id:string;expected_version:number};
export type DtmGradeReportAction={kind:'save_dtm_grade_report';payload:DtmGradeReportTarget&{report:DtmGradeReportContent}}|{kind:'delete_dtm_grade_report';payload:DtmGradeReportTarget};
export type DtmGradeReportReceipt={id:string;userId:string;courseId:string;kind:DtmGradeReportKind;version:number;summary:string};
export type DtmGradeReportAccount=AffairsAccount&{requestDeadline?:number};
export const dtmGradeReportKinds:readonly DtmGradeReportKind[];
export const dtmGradeReportMaxPayloadBytes:131072;
export const dtmGradeReportMaxResponseBytes:196608;
export const dtmGradeReportMaxItems:500;
export const dtmGradeReportReadSource:Readonly<{table:string;select:string;order:string}>;
export class DtmGradeReportError extends Error{status:number;constructor(message:string,status?:number);}
export function dtmGradeReportPayloadBytes(value:unknown):number;
export function validateDtmGradeReportContent(value:unknown):string|null;
export function validateDtmGradeReportPayload(kind:unknown,value:unknown):string|null;
export function parseDtmGradeReportData(value:unknown,userId:string,courseId:string):DtmGradeReportData;
export function parseDtmGradeReportCoursesData(value:unknown,userId:string,afterId?:string):DtmGradeReportCoursesData;
export function parseDtmGradeReportOverviewData(value:unknown,userId:string,afterId?:string):DtmGradeReportOverviewData;
export function parseDtmGradeReportReceipt(value:unknown,kind:DtmGradeReportKind,payload:DtmGradeReportTarget):DtmGradeReportReceipt;
export function loadDtmGradeReport(account:DtmGradeReportAccount,options:{courseId:string}):Promise<DtmGradeReportData>;
export function loadDtmGradeReportAdmin(account:DtmGradeReportAccount,options:{userId:string;courseId:string}):Promise<DtmGradeReportData>;
export function loadDtmGradeReportCoursesAdmin(account:DtmGradeReportAccount,options:{userId:string;afterId?:string}):Promise<DtmGradeReportCoursesData>;
export type DtmGradeOverviewObservation={callerId:string;method:'POST';path:'/rest/v1/rpc/dtm_grade_report_overview';body:{p_after_id?:string};raw:unknown};
export function loadDtmGradeReportOverview(account:DtmGradeReportAccount,options?:{afterId?:string},observeRead?:(read:DtmGradeOverviewObservation)=>void):Promise<DtmGradeReportOverviewData>;
export function manageDtmGradeReport(account:DtmGradeReportAccount,kind:DtmGradeReportKind,payload:unknown):Promise<DtmGradeReportReceipt>;
